import {CHAPTERS,levelRecipe} from './recipes.js';
export const DISHES=['Пирожки','Блины','Пельмени','Борщ','Сырники'];
export function goalText(g){return (g.goals??[{kind:'score'}]).map(x=>x.kind==='score'?`${g.target} очков`:`${DISHES[x.type]}: ${x.amount}`).join(' · ');}
export function goalMarkup(g){return (g.goals??[]).filter(x=>x.kind==='food').map(x=>`<span class="dish-goal" aria-label="${DISHES[x.type]}: ${Math.min(g.collected[x.type],x.amount)} из ${x.amount}"><span class="food f${x.type}" aria-hidden="true"></span><span>${Math.min(g.collected[x.type],x.amount)}<small>/${x.amount}</small></span>${g.collected[x.type]>=x.amount?'<span class="goal-check" aria-hidden="true">✓</span>':''}</span>`).join('');}
export function renderBook(root,data,page,onSelect,onRecipe,onNav){
 const chapter=CHAPTERS[page%3],first=page*6+1,done=new Set(data.completed),complete=Array.from({length:6},(_,i)=>first+i).every(n=>done.has(n));
 root.innerHTML=`<div class="book-heading"><span class="food f${chapter.types[0]} book-dish" aria-hidden="true"></span><span>Тетрадь ${Math.floor(page/3)+1} · глава ${page%3+1}</span><h2>${chapter.title}</h2><p>Каждый уровень — маленькое угощение</p></div><div class="book-levels">${Array.from({length:6},(_,i)=>{const n=first+i,r=levelRecipe(n);return `<button class="recipe-level ${done.has(n)?'complete':''}" data-level="${n}" ${n>data.unlocked?'disabled':''}><b>${done.has(n)?'✓ ':''}${n}</b><span>${r.title}</span><small>${n>data.unlocked?'Пока закрыт':r.goals.some(g=>g.kind==='food')?'Собрать блюда':'Набрать очки'}</small></button>`;}).join('')}</div><button class="button secondary recipe-unlock" id="chapter-recipe">${complete?'Открыть рецепт':'Рецепт откроется после 6 уровней'}<small>${chapter.dish}</small></button><div class="book-pager"><button class="round-button" id="chapter-prev" aria-label="Предыдущая глава" ${page===0?'disabled':''}>‹</button><span>${page+1} / ${Math.max(3,Math.floor((data.unlocked-1)/6)+1)}</span><button class="round-button" id="chapter-next" aria-label="Следующая глава" ${page>=Math.max(2,Math.floor((data.unlocked-1)/6))?'disabled':''}>›</button></div>`;
 root.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>onSelect(Number(b.dataset.level)));
 root.querySelector('#chapter-recipe').onclick=()=>onRecipe(chapter,complete);
 root.querySelector('#chapter-prev').onclick=()=>onNav(page-1);root.querySelector('#chapter-next').onclick=()=>onNav(page+1);
}
